ze"}, {"value": "VAGUE", "target": "refine_issue"}], "position": {"x": 240, "y": 560}, "status_label": "checking clarity result", "max_iterations": 1, "condition_field": "clarity_status", "max_iterations_target": "vague_fail"}, {"id": "vague_fail", "name": "Too Vague", "type": "failed", "targets": [], "position": {"x": 0, "y": 700}, "reason_template": "Issue #{{issue_number}} is still too vague after refinement: {{clarity_reason}}"}, {"id": "analyze", "name": "Analyze Project", "type": "claude_agent", "model": "claude-sonnet-4-6", "retry": {"max_attempts": 1}, "outputs": [{"name": "project_context", "values": []}], "targets": ["plan"], "timeout": 600, "position": {"x": 240, "y": 700}, "status_label": "analyzing project", "prompt_template": "You are a PROJECT ANALYST agent. Explore the codebase and gather context for implementing issue #{{issue_number}}: {{issue_title}}.\\n\\n{{issue_body}}\\n\\n## Instructions\\n1. Run to get the latest code.\\n2. Explore the project structure — check key directories, configs, and conventions.\\n3. Look at recent commits with  to understand current development patterns.\\n4. Find files and code relevant to this issue.\\n5. Note the tech stack, coding patterns, and conventions used.\\n6. Check if needed APIs, DB tables, services, or dependencies exist.\\n\\n## Output\\nProvide a concise project context summary covering:\\n- Relevant files and their purpose\\n- Coding patterns and conventions to follow\\n- Existing code that can be reused\\n- Any technical considerations for the implementation\\n\\nKeep it focused on what the planner and developer need to know. Do NOT write code or create a plan."}, {"id": "plan", "name": "Plan", "type": "claude_agent", "model": "claude-opus-4-6", "retry": {"max_attempts": 1}, "outputs": [{"name": "plan", "values": []}], "targets": ["develop"], "timeout": 600, "position": {"x": 240, "y": 840}, "status_label": "planning", "prompt_template": "You are a PLANNER agent. Create an implementation plan for is